import{_ as s,l as i,o as e,c as l,v as r,p as n,x as o,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"密码破解","description":"","frontmatter":{"title":"密码破解","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/password-cracking.md","filePath":"cs/password-cracking.md","lastUpdated":1789023840000}'),h={name:"cs/password-cracking.md"};function _(m,a,A,E,T,u){const t=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="密码破解" tabindex="-1">密码破解 <a class="header-anchor" href="#密码破解" aria-label="Permalink to &quot;密码破解&quot;">​</a></h1><div class="epigraph"><p>离线猜口令吃的是哈希与熵，不是登录框的速率限制。盐挡住预计算表，慢哈希挡住尝试速率；用户选的口令熵往往仍不够。</p><footer>—— 据 Morris and Thompson, Password Security, CACM 1979；NIST SP 800-63B；Provos and Mazières, bcrypt</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/totp-mfa">TOTP</a>假定第一因素仍常是口令。缺口是<strong>泄漏后的离线猜测</strong>：哈希库一旦出门，攻击者在自己的机器上试。本课讲防御参数，不提供字表或工具教程。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>明文存口令是事故。无盐哈希被彩虹表；快速哈希让 GPU 试亿次。缺口是：盐（每用户）、慢哈希（Argon2/bcrypt/scrypt）、禁止泄露的常见口令、MFA。不重写 HKDF——那是高熵 IKM。</p><h3 id="在线与离线" tabindex="-1">在线与离线 <a class="header-anchor" href="#在线与离线" aria-label="Permalink to &quot;在线与离线&quot;">​</a></h3><p>登录接口要锁定与速率限制；那挡在线。泄漏库是离线，只能靠哈希造价与熵。</p><p><span class="marginnote">Morris–Thompson 1979。NIST 现鼓励长度与检查泄漏集，不强制定期轮换复杂规则。本课禁止破解作业。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照存储：明文 / 快哈希 / 盐+慢哈希。指出 pepper（服务器密钥）是额外，密钥仍要管。下一课生物识别：不可轮换的测量，不是口令。</p>',12)),(e(),n(c,null,{default:o(()=>[p(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PWD%5B%22%E5%8F%A3%E4%BB%A4%22%5D%20--%3E%20SALT%5B%22%E6%AF%8F%E7%94%A8%E6%88%B7%E7%9B%90%22%5D%0A%20%20SALT%20--%3E%20SLOW%5B%22%E6%85%A2%E5%93%88%E5%B8%8C%22%5D%0A%20%20SLOW%20--%3E%20STORE%5B%22%E5%8F%AA%E5%AD%98%E5%93%88%E5%B8%8C%22%5D%0A%20%20ENT%5B%22%E7%94%A8%E6%88%B7%E7%86%B5%22%5D%20--%3E%20COST%5B%22%E7%8C%9C%E6%B5%8B%E4%BB%A3%E4%BB%B7%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>身份单元里口令是共享秘密中最弱的常见形态。哈希参数是把离线猜测推进计算安全游戏。生物下一课把「测你是谁」的错误率写成 FAR/FRR。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给 GPU 配置。生物识别 FAR/FRR 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MFA 之外，口令泄漏走离线猜测。</li><li>盐+慢哈希+拒绝常见口令。</li><li>在线速率限制管不了已泄漏的哈希库。</li><li>下一课生物识别错误率。</li><li>出处：Morris and Thompson, 1979；NIST SP 800-63B；Provos and Mazières, bcrypt。</li></ul>',8))])}const P=s(h,[["render",_]]);export{f as __pageData,P as default};
